#!/usr/bin/env bash
# GSZ step135 — verification-bot inbound owner alert becomes a proper formatted
# message (name / WhatsApp number / email + text) with best-effort customer
# lookup, instead of the raw line. One route patch, no migration. Idempotent.
set -euo pipefail
GSZ=/opt/gsz; TS=$(date +%Y%m%d-%H%M%S); BK="$GSZ/.bak-step135-$TS"; TMP=$(mktemp -d)
FILES=(routes/whatsapp.js)
echo "==> step135: proper verification-bot owner alert"
mkdir -p "$BK"; for f in "${FILES[@]}"; do mkdir -p "$BK/$(dirname "$f")"; cp "$GSZ/$f" "$BK/$f"; done
echo "    backup: $BK"
restore(){ echo "!! FAILED — restoring"; for f in "${FILES[@]}"; do cp "$BK/$f" "$GSZ/$f"; done; pm2 restart gsz >/dev/null 2>&1 || true; echo "!! restored."; }
trap 'restore' ERR
echo "" | base64 -d > "$TMP/p.js"
echo "==> applying"; node "$TMP/p.js" "$GSZ"
echo "==> validating"; node --check "$GSZ/routes/whatsapp.js"
echo "==> restarting"; pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz; sleep 2
CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || true); [ "$CODE" = "200" ] && echo "    homepage 200: OK" || { echo "    homepage $CODE"; false; }
trap - ERR; rm -rf "$TMP"
echo ""; echo "==> step135 OK ✅  When a customer messages the verification number, you now get a formatted alert with their name/number/email (when known) + their message."
